{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table snitch_db.maplemonk.LIQUIDATION_growth_list as Select * from ( With Consol as ( SELECT * from ( Select *, CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END AS extracted_value , REVERSE(SUBSTRING(REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END), CHARINDEX(\'-\', REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END)) + 1)) AS sku_group from ( Select *, case when UNITS_ON_HAND >5 then \'Growth\' else \'Liquidate\' end as status from ( SELECT inv.\"Item SkuCode\" AS sku, SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) AS units_on_hand, COALESCE(SUM(sales.qty), 0) AS last_30d_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 inv LEFT JOIN ( SELECT sku, SUM(suborder_quantity) AS qty FROM snitch_db.maplemonk.unicommerce_fact_items_snitch WHERE marketplace_mapped NOT IN (\'OWN_STORE\',\'CUSTOM\',\'Own Store\',\'FRANCHISE_STORE\',\'Franchise Store\') AND order_date >= CURRENT_DATE - 30 AND shippingpackagestatus IS NOT NULL GROUP BY sku ) sales ON inv.\"Item SkuCode\" = sales.sku WHERE inv.date = CURRENT_DATE AND CAST(inv.facility AS VARCHAR) IN (\'SAPL-WH2\', \'SAPL_EMIZA\', \'SAPL-WH1\') GROUP BY inv.\"Item SkuCode\" HAVING SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) > 0 ) where LAST_30D_QTY =0 ) ) ), class as ( Select * from ( Select * , ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1) AS rn from snitch_db.maplemonk.availability_master_v2) where rn =1) Select a.*, b.sku_class, b.category from consol a left join class b on a.EXTRACTED_VALUE = b.sku_group ) where sku_class !=\'Not-Cataloged\'; Create or replace table snitch_db.maplemonk.doi_list as Select * , CASE WHEN DOI =0 THEN \'No Sales\' WHEN DOI > 0 and DOI < 30 THEN \'0-30\' WHEN DOI >= 30 AND DOI < 60 THEN \'30-60\' WHEN DOI >= 60 AND DOI < 90 THEN \'60-90\' WHEN DOI >= 90 AND DOI < 120 THEN \'90-120\' WHEN DOI >= 120 AND DOI < 150 THEN \'120-150\' WHEN DOI >= 150 AND DOI < 180 THEN \'150-180\' WHEN DOI >= 180 AND DOI < 210 THEN \'180-210\' WHEN DOI >= 210 AND DOI < 240 THEN \'210-240\' WHEN DOI >= 240 AND DOI < 270 THEN \'240-270\' WHEN DOI >= 270 AND DOI < 300 THEN \'270-300\' WHEN DOI >= 300 AND DOI < 330 THEN \'300-330\' WHEN DOI >= 330 AND DOI < 360 THEN \'330-360\' WHEN DOI >= 360 AND DOI < 720 THEN \'360-720\' WHEN DOI >= 720 AND DOI < 1000 THEN \'720-1000\' ELSE \'> 1000\' END AS DOI_Interals, from ( Select *, case when LAST_30D_QTY = 0 then 0 else div0(UNITS_ON_HAND,LAST_30D_QTY)*90 END as DOI from ( With Consol as ( SELECT * from ( Select *, CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END AS extracted_value , REVERSE(SUBSTRING(REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END), CHARINDEX(\'-\', REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END)) + 1)) AS sku_group from ( Select *, case when UNITS_ON_HAND >5 then \'Growth\' else \'Liquidate\' end as status from ( SELECT inv.\"Item SkuCode\" AS sku, SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) AS units_on_hand, COALESCE(SUM(sales.qty), 0) AS last_30d_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 inv LEFT JOIN ( SELECT sku, SUM(suborder_quantity) AS qty FROM snitch_db.maplemonk.unicommerce_fact_items_snitch WHERE marketplace_mapped NOT IN (\'OWN_STORE\',\'CUSTOM\',\'Own Store\',\'FRANCHISE_STORE\',\'Franchise Store\') AND order_date >= CURRENT_DATE - 90 AND shippingpackagestatus IS NOT NULL GROUP BY sku ) sales ON inv.\"Item SkuCode\" = sales.sku WHERE inv.date = CURRENT_DATE AND CAST(inv.facility AS VARCHAR) IN (\'SAPL-WH2\', \'SAPL_EMIZA\', \'SAPL-WH1\') GROUP BY inv.\"Item SkuCode\" HAVING SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) > 0 ) ) ) ), class as ( Select * from ( Select * , ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1) AS rn from snitch_db.maplemonk.availability_master_v2) where rn =1) Select a.*, b.sku_class, b.category from consol a left join class b on a.EXTRACTED_VALUE = b.sku_group ) ); Create or replace table snitch_db.maplemonk.overall_aging_v2 as With overall as ( Select * from snitch_db.maplemonk.overall_aging ), Under_future_production as ( Select distinct sku_group from ( select distinct sku_group from snitch_db.maplemonk.eoq_table_v3 where eoq_new>=500 and final_ros >=15 and discount_per <=25 and average_return_since_first_order <=25 and qup_flag_1 is null and ytbc_status is null and lower(CATEGORY) NOT in (\'accessories\',\'shoes\',\'sunglasses\',\'perfumes\',\'gift cards\',\'jackets\',\'hoodies\',\'sweaters\',\'sweatshirts\') and FABRIC_STATUS NOT LIKE \'%Fabric not Available%\' and \"Best Seller Channel\" is not null and SHIPPED_FROM_FACTORY IS NULL union all Select distinct SKU_GROUP FROM snitch_db.MAPLEMONK.FACTORY_PRODUCTION_INVENTORY union all SELECT distinct SKU_GROUP AS sku_group FROM ( SELECT SKU_GROUP, FACTORY, CASE WHEN TRY_TO_DATE(EXPECTED_DEL_DATE, \'YYYY-MM-DD\') IS NOT NULL THEN TO_DATE(EXPECTED_DEL_DATE, \'YYYY-MM-DD\') WHEN TRY_TO_DATE(EXPECTED_DEL_DATE, \'DD-MM-YYYY\') IS NOT NULL THEN TO_DATE(EXPECTED_DEL_DATE, \'DD-MM-YYYY\') ELSE NULL END AS expected_del_date, CUT_QTY, \'YTBC\' AS Status, FROM snitch_db.maplemonk.factory_up_ytbc_eoq) GROUP BY 1 ) ) Select a.* , case when b.sku_group is not null then \'Yes\' else \'NO\' End as Production_stage from overall a left join under_future_production b on a.sku_group =b.sku_group ; CREATE or replace table snitch_db.maplemonk.b2b_master as With masterr as ( WITH Master AS ( SELECT * FROM ( WITH sku_group_data AS ( SELECT sku_group, branch_code, order_date, suborder_quantity, return_quantity FROM ( WITH ABS AS ( SELECT sku_group, branch_code, order_date, suborder_quantity FROM snitch_db.MAPLEMONK.STORE_fact_items_offline where marketplace_mapped =\'SNITCH - WH - B2B\' ), ACC AS ( SELECT sku_group, branch_code, order_date, suborder_quantity AS return_quantity FROM snitch_db.MAPLEMONK.store_returns_fact_items where marketplace_mapped =\'SNITCH - WH - B2B\' ) SELECT A.*, IFNULL(B.return_quantity, 0) AS return_quantity FROM ABS A FULL OUTER JOIN ACC B ON A.sku_group = B.sku_group AND A.order_date = B.order_date AND A.branch_code = B.branch_code ) WHERE SKU_GROUP NOT LIKE \'CB%\' ), first_order_dates AS ( SELECT sku_group, branch_code, MIN(order_date) AS first_order_date, DATEDIFF(\'DAY\', MIN(order_date), CURRENT_DATE) AS days_since_first_order, DATEDIFF(\'DAY\', MIN(order_date), MAX(order_date)) AS total_days_sold FROM sku_group_data GROUP BY sku_group, branch_code ), total_sales AS ( SELECT sku_group_data.sku_group, sku_group_data.branch_code, first_order_dates.first_order_date, first_order_dates.days_since_first_order, first_order_dates.total_days_sold, SUM(return_quantity) AS total_returns, SUM(suborder_quantity) AS total_sales, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 30, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_30_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 15, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_15_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 7, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_7_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 90, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_90_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 60, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_60_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 180, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_180_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 30 THEN suborder_quantity ELSE 0 END) AS sales_last_30_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 15 THEN suborder_quantity ELSE 0 END) AS sales_last_15_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 7 THEN suborder_quantity ELSE 0 END) AS sales_last_7_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 60 THEN suborder_quantity ELSE 0 END) AS sales_last_60_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 90 THEN suborder_quantity ELSE 0 END) AS sales_last_90_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 180 THEN suborder_quantity ELSE 0 END) AS sales_last_180_days, CASE WHEN first_order_dates.total_days_sold = 0 THEN SUM(suborder_quantity) ELSE SUM(suborder_quantity) / first_order_dates.total_days_sold END AS natural_ros FROM sku_group_data INNER JOIN first_order_dates ON sku_group_data.sku_group = first_order_dates.sku_group AND sku_group_data.branch_code = first_order_dates.branch_code GROUP BY sku_group_data.sku_group, sku_group_data.branch_code, first_order_dates.first_order_date, first_order_dates.days_since_first_order, first_order_dates.total_days_sold ), enhanced_total_sales AS ( SELECT total_sales.*, GREATEST( total_sales.sales_first_30_days / 30, total_sales.sales_last_30_days / 30, total_sales.natural_ros ) AS max_first_30_last_30_natural_ros, GREATEST( total_sales.sales_first_30_days / 30, total_sales.sales_last_30_days / 30, total_sales.natural_ros, total_sales.sales_first_7_days / 7 ) AS max_first_30_last_30_natural_ros_first_7_days, CASE WHEN total_sales.total_sales = 0 THEN 0 ELSE (total_sales.total_returns / total_sales.total_sales) * 100 END AS average_return_since_first_order, CASE WHEN max_first_30_last_30_natural_ros > 10 THEN max_first_30_last_30_natural_ros WHEN max_first_30_last_30_natural_ros < 10 AND max_first_30_last_30_natural_ros_first_7_days > 20 THEN max_first_30_last_30_natural_ros_first_7_days WHEN total_sales.total_sales > 800 THEN GREATEST(natural_ros, sales_last_7_days / 7) ELSE natural_ros END AS final_ros FROM total_sales ) SELECT * FROM enhanced_total_sales ORDER BY total_sales DESC ) ), inventory AS ( SELECT CASE WHEN UPPER(ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN ADDLITEMCODE) > 0 THEN SPLIT_PART(ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(ADDLITEMCODE, \'-\', 2) ELSE ADDLITEMCODE END as sku_group, BRANCH_CODE, SUM(STOCK_QTY) AS inventory, DATE, COALESCE(SUM(CASE WHEN PACK_NAME = \'XS\' OR PACK_NAME = \'28\' THEN STOCK_QTY ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'S\' OR PACK_NAME = \'30\' THEN STOCK_QTY ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'M\' OR PACK_NAME = \'32\' THEN STOCK_QTY ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'L\' OR PACK_NAME = \'34\' THEN STOCK_QTY ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'XL\' OR PACK_NAME = \'36\' THEN STOCK_QTY ELSE 0 END), 0) AS XL_units, COALESCE(SUM(CASE WHEN PACK_NAME IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN STOCK_QTY ELSE 0 END), 0) AS XXL_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'3XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL3_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'4XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL4_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'5XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL5_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'6XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL6_units, (CASE WHEN XS_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_units > 0 THEN 1 ELSE 0 END) AS num_size_available FROM snitch_db.maplemonk.logic_virtual_b2b_ho_get_stock_in_hand WHERE sku_group NOT LIKE \'CB%\' AND DATE = CURRENT_DATE and branch_name = \'SNITCH - WH - B2B\' GROUP BY sku_group, branch_code, DATE ) SELECT COALESCE(q.sku_group, b.sku_group) as SKU_GROUP_Final, COALESCE(q.branch_code, b.branch_code) as Store, COALESCE(q.TOTAL_RETURNS, 0) AS TOTAL_RETURNS, COALESCE(q.FIRST_ORDER_DATE, null) AS FIRST_ORDER_DATE, COALESCE(q.DAYS_SINCE_FIRST_ORDER, 0) AS DAYS_SINCE_FIRST_ORDER, COALESCE(q.TOTAL_SALES, 0) AS TOTAL_SALES, COALESCE(q.NATURAL_ROS, 0) AS NATURAL_ROS, COALESCE(q.AVERAGE_RETURN_SINCE_FIRST_ORDER, 0) AS AVERAGE_RETURN_SINCE_FIRST_ORDER, COALESCE(q.FINAL_ROS, 0) AS FINAL_ROS, COALESCE(q.SALES_FIRST_7_DAYS, 0) AS SALES_FIRST_7_DAYS, COALESCE(q.SALES_FIRST_15_DAYS, 0) AS SALES_FIRST_15_DAYS, COALESCE(q.SALES_FIRST_30_DAYS, 0) AS SALES_FIRST_30_DAYS, COALESCE(q.SALES_LAST_7_DAYS, 0) AS SALES_LAST_7_DAYS, COALESCE(q.SALES_LAST_15_DAYS, 0) AS SALES_LAST_15_DAYS, COALESCE(q.SALES_LAST_30_DAYS, 0) AS SALES_LAST_30_DAYS, COALESCE(b.INVENTORY, 0) AS INVENTORY, COALESCE(b.XS_UNITS, 0) as XS_UNITS, COALESCE(b.S_UNITS, 0) as S_UNITS, COALESCE(b.M_UNITS, 0) as M_UNITS, COALESCE(b.L_UNITS, 0) as L_UNITS, COALESCE(b.XL_UNITS, 0) as XL_UNITS, COALESCE(b.XXL_UNITS, 0) as XXL_UNITS, COALESCE(b.XL3_UNITS, 0) as XL3_UNITS, COALESCE(b.XL4_UNITS, 0) as XL4_UNITS, COALESCE(b.XL5_UNITS, 0) as XL5_UNITS, COALESCE(b.XL6_UNITS, 0) as XL6_UNITS, COALESCE(b.NUM_SIZE_AVAILABLE, 0) as NUM_SIZE_AVAILABLE FROM Master q FULL OUTER JOIN Inventory b ON q.sku_group = b.sku_group AND q.branch_code = b.branch_code ), cat as (Select * from (SELECT sku_group, Category, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1 DESC) AS rn FROM snitch_db.maplemonk.metafields_data) where rn = 1), ava as ( Select * from ( select *,ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1 DESC) AS rn from snitch_db.maplemonk.availability_master_v2) where rn=1) Select a.*, COALESCE( b.Category, CASE WHEN SKU_GROUP_Final LIKE \'4MSR%\' THEN \'Trousers\' WHEN SKU_GROUP_Final LIKE \'4MSD%\' THEN \'Jeans\' WHEN SKU_GROUP_Final LIKE \'4MVK%\' THEN \'Jeans\' WHEN SKU_GROUP_Final LIKE \'4MSS%\' THEN \'Shirts\' WHEN SKU_GROUP_Final LIKE \'4MST%\' THEN \'T-Shirts\' WHEN SKU_GROUP_Final LIKE \'4MBGVK%\' THEN \'Jeans\' WHEN SKU_GROUP_Final LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN SKU_GROUP_Final LIKE \'4MSBX%\' THEN \'Boxers\' WHEN SKU_GROUP_Final LIKE \'4MSO%\' THEN \'Cargo Pants\' ELSE NULL END ) AS product_type, c.sku_class from masterr a left join cat b on a.SKU_GROUP_Final =b.sku_group left join ava c on a.SKU_GROUP_Final =c.sku_group; CREATE or REPLACE table snitch_db.maplemonk.b2b_Inventory as SELECT sih.addlitemcode, CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END as sku_group, sih.branch_code, sih.branch_name, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\') AS lot_pur_date_converted, sih.lot_mrp, sih.lot_sprate1, sih.stock_qty, DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) AS aging_days, COALESCE( md.Category, CASE WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MSR%\' THEN \'Trousers\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MSD%\' THEN \'Jeans\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MVK%\' THEN \'Jeans\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MSS%\' THEN \'Shirts\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MST%\' THEN \'T-Shirts\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MBGVK%\' THEN \'Jeans\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MSBX%\' THEN \'Boxers\' WHEN CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END LIKE \'4MSO%\' THEN \'Cargo Pants\' ELSE NULL END ) AS product_type, CASE WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 30 THEN \'0-30\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 60 THEN \'31-60\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 90 THEN \'61-90\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 120 THEN \'91-120\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 150 THEN \'121-150\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 180 THEN \'151-180\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 210 THEN \'181-210\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 240 THEN \'211-240\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 270 THEN \'241-270\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 300 THEN \'271-300\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 330 THEN \'301-330\' WHEN DATEDIFF(DAY, TO_DATE(sih.lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE()) <= 360 THEN \'331-360\' ELSE \'>360\' END AS aging_bucket FROM snitch_db.maplemonk.logic_virtual_b2b_ho_get_stock_in_hand sih LEFT JOIN ( Select * from (SELECT sku_group, Category, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1 DESC) AS rn FROM snitch_db.maplemonk.metafields_data) where rn = 1 ) md ON md.sku_group = CASE WHEN UPPER(sih.ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN sih.ADDLITEMCODE) > 0 THEN SPLIT_PART(sih.ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(sih.ADDLITEMCODE, \'-\', 2) ELSE sih.ADDLITEMCODE END WHERE sih.branch_name = \'SNITCH - WH - B2B\' and TO_DATE(sih.date, \'YYYY-MM-DD\') = current_date;",
